mapper.select:
select t.event_id,t.event_id eventId,t.remark,t.status_cd,t.status_cd statusCd,t.event_type,t.event_type
eventType,t.event_msg,t.event_msg eventMsg,t.from_type,t.from_type fromType,t.from_name,t.from_name
fromName,t.object_name,t.object_name objectName,t.state,t.rule_id,t.rule_id ruleId,t.community_id,t.community_id
communityId,t.obj_type,t.obj_type objType,t.object_id,t.object_id objectId,t.create_time createTime,er.rule_name ruleName,
td.name eventTypeName, td1.name objTypeName
from event_pool t
left join event_rule er on t.rule_id = er.rule_id
left join event_template et on er.template_id = et.template_id
left join t_dict td on t.event_type = td.status_cd and td.table_name = 'event_pool' and td.table_columns = 'event_type'
left join t_dict td1 on t.obj_type = td1.status_cd and td1.table_name = 'event_object' and td1.table_columns = 'obj_type'
where 1 =1 and er.status_cd = '0' and et.status_cd = '0'

    and t.event_id= #{eventId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.event_type= #{eventType}


    and t.event_msg= #{eventMsg}


    and t.from_type= #{fromType}


    and t.from_name= #{fromName}


    and t.object_name= #{objectName}


    and t.state= #{state}


    and t.rule_id= #{ruleId}


    and t.community_id= #{communityId}


    and t.obj_type= #{objType}


    and t.object_id= #{objectId}

order by t.create_time desc

    limit #{page}, #{row}

